import os
import requests

def diarized_transcript(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["ASSEMBLYAI_API_KEY"]
    headers = {"authorization": api_key, "content-type": "application/json"}
    data = {
        "audio_url": payload["audio_url"],
        "speaker_labels": True,
    }
    if "speakers_expected" in payload:
        data["speakers_expected"] = payload["speakers_expected"]
    resp = requests.post("https://api.assemblyai.com/v2/transcript", json=data, headers=headers, timeout=60)
    resp.raise_for_status()
    transcript = resp.json()
    transcript_id = transcript["id"]

    polling_endpoint = f"https://api.assemblyai.com/v2/transcript/{transcript_id}"
    while True:
        poll = requests.get(polling_endpoint, headers=headers, timeout=60)
        poll.raise_for_status()
        poll_data = poll.json()
        status = poll_data.get("status")
        if status == "completed":
            utterances = poll_data.get("utterances") or []
            if not utterances:
                return {
                    "id": transcript_id,
                    "status": status,
                    "text": poll_data.get("text", ""),
                    "utterances": [],
                    "provider": "assemblyai",
                }
            return {
                "id": transcript_id,
                "status": status,
                "text": poll_data.get("text", ""),
                "utterances": [
                    {
                        "speaker": u.get("speaker"),
                        "text": u.get("text", ""),
                        "start": u.get("start"),
                        "end": u.get("end"),
                        "confidence": u.get("confidence"),
                    }
                    for u in utterances
                ],
                "provider": "assemblyai",
            }
        if status == "error":
            raise RuntimeError(poll_data.get("error", "AssemblyAI transcription failed"))
    result = None
    return result
